    "inlineSchema": "generator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\nenum UserRole {\n  CUSTOMER\n  BUSINESS_OWNER\n  ADMIN\n}\n\nenum BookingStatus {\n  PENDING\n  CONFIRMED\n  COMPLETED\n  CANCELLED\n  NO_SHOW\n}\n\nenum PaymentStatus {\n  PENDING\n  COMPLETED\n  FAILED\n  REFUNDED\n}\n\nenum NotificationType {\n  BOOKING_CONFIRMATION\n  BOOKING_REMINDER\n  BOOKING_CANCELLATION\n  PAYMENT_RECEIVED\n  NEW_REVIEW\n  APPOINTMENT_APPROACHING\n}\n\nmodel User {\n  id        String   @id @default(cuid())\n  email     String   @unique\n  password  String\n  firstName String\n  lastName  String\n  phone     String?\n  avatar    String?\n  role      UserRole @default(CUSTOMER)\n\n  business           Business?\n  bookingsAsCustomer Booking[]\n  reviews            Review[]\n  notifications      Notification[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel Business {\n  id     String @id @default(cuid())\n  userId String @unique\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  name        String\n  description String?\n  logo        String?\n  coverImage  String?\n  email       String  @unique\n  phone       String\n  website     String?\n  category    String\n\n  address String\n  city    String\n  state   String\n  zipCode String\n  country String\n\n  isVerified Boolean @default(false)\n  isActive   Boolean @default(true)\n  rating     Float   @default(0)\n\n  services  Service[]\n  bookings  Booking[]\n  payments  Payment[]\n  reviews   Review[]\n  hours     BusinessHours[]\n  customers Customer[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel Service {\n  id         String   @id @default(cuid())\n  businessId String\n  business   Business @relation(fields: [businessId], references: [id], onDelete: Cascade)\n\n  name        String\n  description String?\n  price       Float\n  duration    Int\n  image       String?\n  isActive    Boolean @default(true)\n  capacity    Int     @default(1)\n\n  bookings Booking[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel Customer {\n  id         String   @id @default(cuid())\n  businessId String\n  business   Business @relation(fields: [businessId], references: [id], onDelete: Cascade)\n\n  name  String\n  email String\n  phone String\n  notes String?\n\n  totalBookings Int       @default(0)\n  totalSpent    Float     @default(0)\n  lastVisit     DateTime?\n\n  bookings Booking[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([businessId, email])\n}\n\nmodel Booking {\n  id        String  @id @default(cuid())\n  serviceId String\n  service   Service @relation(fields: [serviceId], references: [id], onDelete: Cascade)\n\n  businessId String\n  business   Business @relation(fields: [businessId], references: [id], onDelete: Cascade)\n\n  customerId String?\n  customer   Customer? @relation(fields: [customerId], references: [id], onDelete: SetNull)\n\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  startTime     DateTime\n  endTime       DateTime\n  customerName  String\n  customerEmail String\n  customerPhone String\n  notes         String?\n\n  status BookingStatus @default(PENDING)\n\n  payment       Payment?\n  notifications Notification[] @relation(\"BookingNotifications\")\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel Payment {\n  id        String  @id @default(cuid())\n  bookingId String  @unique\n  booking   Booking @relation(fields: [bookingId], references: [id], onDelete: Cascade)\n\n  businessId String\n  business   Business @relation(fields: [businessId], references: [id], onDelete: Cascade)\n\n  amount   Float\n  currency String        @default(\"USD\")\n  status   PaymentStatus @default(PENDING)\n  method   String?\n\n  transactionId String? @unique\n  receiptUrl    String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel Review {\n  id         String   @id @default(cuid())\n  businessId String\n  business   Business @relation(fields: [businessId], references: [id], onDelete: Cascade)\n\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  rating  Int\n  title   String?\n  comment String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([businessId, userId])\n}\n\nmodel BusinessHours {\n  id         String   @id @default(cuid())\n  businessId String\n  business   Business @relation(fields: [businessId], references: [id], onDelete: Cascade)\n\n  dayOfWeek Int\n  openTime  String\n  closeTime String\n  isClosed  Boolean @default(false)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([businessId, dayOfWeek])\n}\n\nmodel Notification {\n  id     String @id @default(cuid())\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  bookingId String?\n  booking   Booking? @relation(\"BookingNotifications\", fields: [bookingId], references: [id], onDelete: SetNull)\n\n  type    NotificationType\n  title   String\n  message String\n  isRead  Boolean          @default(false)\n\n  createdAt DateTime @default(now())\n}\n",
